{"t":"say","text":"I'll draw a small company website in Singapore with ESA, ALB, two ECS instances and an RDS database."}
{"t":"plan","products":["users","dns","esa","alb","ecs","rds","oss"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Visitors","group":"internet","why":"People browsing the company website."}
