{"t":"say","text":"I'll draw a serverless concert ticketing API on SAE with ALB, Tair cache and PolarDB, no ops needed."}
{"t":"req","text":"Zero ops engineers; use fully managed serverless services"}
{"t":"plan","products":["users","dns","esa","alb","waf","sae","tair","polardb","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Ticket buyers","group":"internet","why":"Fans calling the ticketing API from apps or browsers."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the API domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates and protects API traffic at the edge."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Ticketing VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes HTTP requests to SAE across two zones."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Blocks bots scalping tickets during sales."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"api","product":"sae","label":"Ticketing API","group":"vpc","zones":["a","b"],"why":"Runs the API serverless; autoscales without ops effort."}
{"t":"edge","id":"e-alb-api","from":"alb","to":"api"}
