{"t":"say","text":"I'll design a clinic appointment booking app in Seoul (ap-northeast-2) so all health data stays in South Korea."}
{"t":"req","text":"All health records must never leave South Korea"}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","rds","oss","sls"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Patients","group":"internet","why":"Patients booking appointments online."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the clinic domain to ESA."}
