{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Sessions go to Tair, bookings and health records to RDS. All stay inside the Seoul region."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Stores sessions for fast page loads."}
{"t":"node","id":"db","product":"rds","label":"Bookings DB","group":"vpc","zones":["a","b"],"why":"Stores appointments and health records locally in Seoul."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"media","product":"oss","label":"Static assets","group":"kr","why":"Hosts images and files served via ESA."}
